static int cmpd(const void*a,const void*b){double x=*(double*)a,y=*(double*)b;return x<y?-1:x>y;}

int main(int argc,char**argv){
  void*h=dlopen("/usr/local/lib/python3.13/site-packages/numpy.libs/libscipy_openblas64_-56d6093b.so",RTLD_NOW|RTLD_GLOBAL);
