/* Fast dominant eigenpair for small real matrices.
 *
 * Strategy: Householder reduction to Hessenberg form, Francis double-shift QR
 * for the spectrum, then inverse iteration for the eigenvector of the
 * dominant eigenvalue (largest magnitude).  The result is verified against the
 * exact np.allclose criterion inside C; on failure the caller falls back to
 * numpy.linalg.eig.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>
#include <math.h>
#include <string.h>

#ifndef MAXN
#define MAXN 24
#endif

#define A(i, j) a[(i) * n + (j)]

static inline double sgn(double x, double y) { return y >= 0.0 ? fabs(x) : -fabs(x); }

/* ------------------------------------------------------------------ */
/* Householder reduction to upper Hessenberg form (row-major, in place) */
static void hessenberg(int n, double *a)
{
    double v[MAXN];
    for (int k = 0; k < n - 2; k++) {
        double norm = 0.0;
        for (int i = k + 1; i < n; i++)
            norm += A(i, k) * A(i, k);
        norm = sqrt(norm);
        if (norm == 0.0 || !isfinite(norm))
            continue;
        double x0 = A(k + 1, k);
        double alpha = -sgn(norm, x0);
        double d = x0 - alpha;
        if (d == 0.0)
            continue;
        /* v acts on rows k+1..n-1, scaled so v[0] == 1 */
        v[0] = 1.0;
        double vnorm2 = 1.0;
        for (int i = k + 2; i < n; i++) {
            double t = A(i, k) / d;
            v[i - (k + 1)] = t;
            vnorm2 += t * t;
        }
        double beta = 2.0 / vnorm2;
        for (int j = k; j < n; j++) {
            double s = 0.0;
            for (int i = k + 1; i < n; i++)
                s += v[i - (k + 1)] * A(i, j);
            s *= beta;
            for (int i = k + 1; i < n; i++)
                A(i, j) -= s * v[i - (k + 1)];
        }
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            for (int j = k + 1; j < n; j++)
                s += A(i, j) * v[j - (k + 1)];
            s *= beta;
            for (int j = k + 1; j < n; j++)
                A(i, j) -= s * v[j - (k + 1)];
        }
        for (int i = k + 2; i < n; i++)
            A(i, k) = 0.0;
    }
}

/* ------------------------------------------------------------------ */
/* Francis double-shift QR on a Hessenberg matrix (Numerical Recipes)  */
static void hqr(int n, double *a, double *wr, double *wi)
{
    int nn, m, l, k, j, its, i, mmin;
    double z, y, x, w, v, u, t, s, r, q, p, anorm;

    anorm = fabs(A(0, 0));
    for (i = 1; i < n; i++)
        for (j = i - 1; j < n; j++)
            anorm += fabs(A(i, j));
    nn = n - 1;
    t = 0.0;
    while (nn >= 0) {
        its = 0;
        do {
            for (l = nn; l >= 1; l--) {
                s = fabs(A(l - 1, l - 1)) + fabs(A(l, l));
                if (s == 0.0)
                    s = anorm;
                if (fabs(A(l, l - 1)) + s == s) {
                    A(l, l - 1) = 0.0;
                    break;
                }
            }
            x = A(nn, nn);
            if (l == nn) {
                wr[nn] = x + t;
                wi[nn] = 0.0;
                nn--;
            } else {
                y = A(nn - 1, nn - 1);
                w = A(nn, nn - 1) * A(nn - 1, nn);
                if (l == nn - 1) {
                    p = 0.5 * (y - x);
                    q = p * p + w;
                    z = sqrt(fabs(q));
                    x += t;
                    if (q >= 0.0) {
                        z = p + sgn(z, p);
                        wr[nn - 1] = wr[nn] = x + z;
                        if (z != 0.0)
                            wr[nn] = x - w / z;
                        wi[nn - 1] = wi[nn] = 0.0;
                    } else {
                        wr[nn - 1] = wr[nn] = x + p;
                        wi[nn - 1] = -z;
                        wi[nn] = z;
                    }
                    nn -= 2;
                } else {
                    if (its == 60)
                        return; /* give up; caller verifies */
                    if (its == 10 || its == 20 || its == 40) {
                        t += x;
                        for (i = 0; i <= nn; i++)
                            A(i, i) -= x;
                        s = fabs(A(nn, nn - 1)) + fabs(A(nn - 1, nn - 2));
                        y = x = 0.75 * s;
                        w = -0.4375 * s * s;
                    }
                    ++its;
                    for (m = nn - 2; m >= l; m--) {
                        z = A(m, m);
                        r = x - z;
                        s = y - z;
                        p = (r * s - w) / A(m + 1, m) + A(m, m + 1);
                        q = A(m + 1, m + 1) - z - r - s;
                        r = A(m + 2, m + 1);
                        s = fabs(p) + fabs(q) + fabs(r);
                        p /= s;
                        q /= s;
                        r /= s;
                        if (m == l)
                            break;
                        u = fabs(A(m, m - 1)) * (fabs(q) + fabs(r));
                        v = fabs(p) * (fabs(A(m - 1, m - 1)) + fabs(z) + fabs(A(m + 1, m + 1)));
                        if (u + v == v)
                            break;
                    }
                    for (i = m + 2; i <= nn; i++) {
                        A(i, i - 2) = 0.0;
                        if (i != m + 2)
                            A(i, i - 3) = 0.0;
                    }
                    for (k = m; k <= nn - 1; k++) {
                        if (k != m) {
                            p = A(k, k - 1);
                            q = A(k + 1, k - 1);
                            r = 0.0;
                            if (k != nn - 1)
                                r = A(k + 2, k - 1);
                            x = fabs(p) + fabs(q) + fabs(r);
                            if (x != 0.0) {
                                p /= x;
                                q /= x;
                                r /= x;
                            }
                        }
                        s = sgn(sqrt(p * p + q * q + r * r), p);
                        if (s != 0.0) {
                            if (k == m) {
                                if (l != m)
                                    A(k, k - 1) = -A(k, k - 1);
                            } else {
                                A(k, k - 1) = -s * x;
                            }
                            p += s;
                            x = p / s;
                            y = q / s;
                            z = r / s;
                            q /= p;
                            r /= p;
                            for (j = k; j <= nn; j++) {
                                p = A(k, j) + q * A(k + 1, j);
                                if (k != nn - 1) {
                                    p += r * A(k + 2, j);
                                    A(k + 2, j) -= p * z;
                                }
                                A(k + 1, j) -= p * y;
                                A(k, j) -= p * x;
                            }
                            mmin = nn < k + 3 ? nn : k + 3;
                            for (i = l; i <= mmin; i++) {
                                p = x * A(i, k) + y * A(i, k + 1);
                                if (k != nn - 1) {
                                    p += z * A(i, k + 2);
                                    A(i, k + 2) -= p * r;
                                }
                                A(i, k + 1) -= p * q;
                                A(i, k) -= p;
                            }
                        }
                    }
                }
            }
        } while (l < nn - 1);
    }
}

/* ------------------------------------------------------------------ */
/* LU with partial pivoting (row-major, in place)                      */
static int lu_factor(int n, double *M, int *piv)
{
    for (int k = 0; k < n; k++) {
        int p = k;
        double mx = fabs(M[k * n + k]);
        for (int i = k + 1; i < n; i++) {
            double t = fabs(M[i * n + k]);
            if (t > mx) {
                mx = t;
                p = i;
            }
        }
        piv[k] = p;
        if (mx == 0.0 || !isfinite(mx))
            return 0;
        if (p != k)
            for (int j = 0; j < n; j++) {
                double t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
        double d = M[k * n + k];
        for (int i = k + 1; i < n; i++) {
            double f = M[i * n + k] / d;
            M[i * n + k] = f;
            if (f != 0.0) {
                const double *rowk = M + k * n;
                double *rowi = M + i * n;
                for (int j = k + 1; j < n; j++)
                    rowi[j] -= f * rowk[j];
            }
        }
    }
    return 1;
}

static void lu_solve(int n, const double *LU, const int *piv, double *x)
{
    for (int k = 0; k < n; k++) {
        int p = piv[k];
        if (p != k) {
            double t = x[k];
            x[k] = x[p];
            x[p] = t;
        }
    }
    for (int i = 0; i < n; i++) {
        double s = x[i];
        const double *row = LU + i * n;
        for (int j = 0; j < i; j++)
            s -= row[j] * x[j];
        x[i] = s;
    }
    for (int i = n - 1; i >= 0; i--) {
        double s = x[i];
        const double *row = LU + i * n;
        for (int j = i + 1; j < n; j++)
            s -= row[j] * x[j];
        x[i] = s / row[i];
    }
}

/* inverse iteration: w <- (M^-1 w), a couple of times */
static int inverse_iter(int n, const double *LU, const int *piv, double *w, int iters)
{
    double tmp[MAXN];
    for (int it = 0; it < iters; it++) {
        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += w[i] * w[i];
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            return 0;
        for (int i = 0; i < n; i++)
            tmp[i] = w[i] / nrm;
        lu_solve(n, LU, piv, tmp);
        for (int i = 0; i < n; i++) {
            if (!isfinite(tmp[i]))
                return 0;
            w[i] = tmp[i];
        }
    }
    return 1;
}

/* check np.allclose(A v, lambda v) componentwise, with a safety margin */
static int residual_ok(int n, const double *avr, const double *avi,
                       double lr, double li,
                       const double *vr, const double *vi)
{
    /* compare complex arrays with rtol=1e-5, atol=1e-8, half margin */
    const double atol = 5e-9, rtol = 5e-6;
    for (int i = 0; i < n; i++) {
        double pr = lr * vr[i] - li * vi[i];
        double pi = lr * vi[i] + li * vr[i];
        double dr = fabs(avr[i] - pr);
        double di = fabs(avi[i] - pi);
        double thr_r = atol + rtol * fabs(pr);
        double thr_i = atol + rtol * fabs(pi);
        if (dr > thr_r || di > thr_i)
            return 0;
    }
    return 1;
}

/* ------------------------------------------------------------------ */
static PyObject *dominant(PyObject *self, PyObject *args)
{
    Py_buffer view;
    if (!PyArg_ParseTuple(args, "y*", &view))
        return NULL;

    int n;
    const double *Ain;
    Py_ssize_t ndim = 1;
    /* buffer protocol on a numpy array: use PyObject_GetBuffer for shape info */
    PyBuffer_Release(&view);

    return NULL; /* placeholder, replaced below */
}

/* real entry point: takes the numpy array object directly */
static PyObject *dominant_arr(PyObject *self, PyObject *arg)
{
    PyArrayObject *arr = (PyArrayObject *)arg;
    if (!PyArray_Check(arr))
        Py_RETURN_NONE;
    int n = (int)PyArray_DIM(arr, 0);
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr, 1) != n || n < 1 || n > MAXN)
        Py_RETURN_NONE;
    double *A = (double *)PyArray_DATA(arr);
    npy_intp s0 = PyArray_STRIDE(arr, 0), s1 = PyArray_STRIDE(arr, 1);

    double a[MAXN * MAXN];
    for (int i = 0; i < n; i++) {
        const char *row = (const char *)A + i * s0;
        for (int j = 0; j < n; j++)
            a[i * n + j] = *(const double *)(row + j * s1);
    }

    /* --- spectrum --- */
    double h[MAXN * MAXN];
    memcpy(h, a, sizeof(double) * n * n);
    hessenberg(n, h);
    double wr[MAXN], wi[MAXN];
    hqr(n, h, wr, wi);

    /* --- dominant eigenvalue selection (ties prefer positive imag, like LAPACK) --- */
    int idx = 0;
    double best = -1.0;
    for (int i = 0; i < n; i++) {
        double mag = hypot(wr[i], wi[i]);
        if (!isfinite(mag))
            Py_RETURN_NONE;
        if (mag > best) {
            best = mag;
            idx = i;
        } else if (mag >= best * (1.0 - 1e-12) && wi[i] > 0.0 && wi[idx] < 0.0) {
            idx = i;
        }
    }
    double lr = wr[idx], li = wi[idx];

    double anorm = 0.0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            anorm += a[i * n + j] * a[i * n + j];
    anorm = sqrt(anorm);

    double M[MAXN * MAXN], w[MAXN], tmp[MAXN];
    int piv[MAXN];

    if (fabs(li) <= 1e-9 * (fabs(lr) + anorm)) {
        /* ---------- real eigenvalue ---------- */
        li = 0.0;
        memcpy(M, a, sizeof(double) * n * n);
        for (int i = 0; i < n; i++)
            M[i * n + i] -= lr;
        if (!lu_factor(n, M, piv))
            Py_RETURN_NONE;
        for (int i = 0; i < n; i++)
            w[i] = 1.0 + 0.5 * (double)i;
        if (!inverse_iter(n, M, piv, w, 3))
            Py_RETURN_NONE;
        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += w[i] * w[i];
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            Py_RETURN_NONE;
        for (int i = 0; i < n; i++)
            w[i] /= nrm;

        /* Rayleigh quotient and residual */
        double aw[MAXN], num = 0.0;
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            const double *row = a + i * n;
            for (int j = 0; j < n; j++)
                s += row[j] * w[j];
            aw[i] = s;
            num += w[i] * s;
        }
        lr = num; /* ||w|| == 1 */
        if (!residual_ok(n, aw, (const double *)0 + 0, lr, 0.0, w, NULL))
            ; /* handled below with zero imag parts */
        /* real residual check (imag parts are zero) */
        {
            int ok = 1;
            for (int i = 0; i < n; i++) {
                double pr = lr * w[i];
                if (fabs(aw[i] - pr) > 5e-9 + 5e-6 * fabs(pr)) {
                    ok = 0;
                    break;
                }
            }
            if (!ok)
                Py_RETURN_NONE;
        }
        npy_intp dims[1] = {n};
        PyObject *vec = PyArray_SimpleNew(1, dims, NPY_DOUBLE);
        if (!vec)
            return NULL;
        memcpy(PyArray_DATA((PyArrayObject *)vec), w, sizeof(double) * n);
        PyObject *val = PyArray_Scalar(&lr, PyArray_DescrFromType(NPY_DOUBLE), NULL);
        PyObject *res = PyTuple_Pack(2, val, vec);
        Py_DECREF(val);
        Py_DECREF(vec);
        return res;
    } else {
        /* ---------- complex conjugate pair ---------- */
        /* M = (A - lr I)^2 + li^2 I ; null space = invariant subspace */
        double B[MAXN * MAXN];
        memcpy(B, a, sizeof(double) * n * n);
        for (int i = 0; i < n; i++)
            B[i * n + i] -= lr;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double s = 0.0;
                const double *ri = B + i * n;
                for (int k = 0; k < n; k++)
                    s += ri[k] * B[k * n + j];
                M[i * n + j] = s;
            }
            M[i * n + i] += li * li;
        }
        if (!lu_factor(n, M, piv))
            Py_RETURN_NONE;
        for (int i = 0; i < n; i++)
            w[i] = 1.0 + 0.5 * (double)i;
        if (!inverse_iter(n, M, piv, w, 3))
            Py_RETURN_NONE;

        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += w[i] * w[i];
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            Py_RETURN_NONE;
        for (int i = 0; i < n; i++)
            w[i] /= nrm;

        /* z = (A w - lr w)/li ;  v = w - i z */
        double z[MAXN];
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            const double *row = a + i * n;
            for (int j = 0; j < n; j++)
                s += row[j] * w[j];
            z[i] = (s - lr * w[i]) / li;
        }
        /* v = wr + i vi with wr = w, vi = -z */
        double vr[MAXN], vi[MAXN], avr[MAXN], avi[MAXN];
        for (int i = 0; i < n; i++) {
            vr[i] = w[i];
            vi[i] = -z[i];
        }
        for (int i = 0; i < n; i++) {
            double sr = 0.0, si = 0.0;
            const double *row = a + i * n;
            for (int j = 0; j < n; j++) {
                sr += row[j] * vr[j];
                si += row[j] * vi[j];
            }
            avr[i] = sr;
            avi[i] = si;
        }
        /* Rayleigh quotient v^H A v / v^H v */
        double numr = 0.0, numi = 0.0, den = 0.0;
        for (int i = 0; i < n; i++) {
            numr += vr[i] * avr[i] + vi[i] * avi[i];
            numi += vr[i] * avi[i] - vi[i] * avr[i];
            den += vr[i] * vr[i] + vi[i] * vi[i];
        }
        if (!(den > 0.0) || !isfinite(den))
            Py_RETURN_NONE;
        lr = numr / den;
        li = numi / den;
        if (!residual_ok(n, avr, avi, lr, li, vr, vi))
            Py_RETURN_NONE;

        npy_intp dims[1] = {n};
        PyObject *vec = PyArray_SimpleNew(1, dims, NPY_CDOUBLE);
        if (!vec)
            return NULL;
        npy_cdouble *out = (npy_cdouble *)PyArray_DATA((PyArrayObject *)vec);
        for (int i = 0; i < n; i++) {
            out[i].real = vr[i];
            out[i].imag = vi[i];
        }
        npy_cdouble lam;
        lam.real = lr;
        lam.imag = li;
        PyObject *val = PyArray_Scalar(&lam, PyArray_DescrFromType(NPY_CDOUBLE), NULL);
        PyObject *res = PyTuple_Pack(2, val, vec);
        Py_DECREF(val);
        Py_DECREF(vec);
        return res;
    }
}

static PyMethodDef Methods[] = {
    {"dominant", dominant_arr, METH_O, "dominant eigenpair"},
    {NULL, NULL, 0, NULL},
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigenfast", NULL, -1, Methods,
};

PyMODINIT_FUNC PyInit__eigenfast(void)
{
    import_array();
    return PyModule_Create(&moduledef);
}

