/* Numeric core: dominant eigenpair of a small real square matrix.
 *
 * Householder reduction to Hessenberg form, Francis double-shift QR for the
 * spectrum, then inverse iteration for the eigenvector of the eigenvalue of
 * largest magnitude.  Everything is verified against the exact np.allclose
 * criterion before being handed back, so a caller may fall back to LAPACK.
 */
#ifndef EIGEN_CORE_H
#define EIGEN_CORE_H

#include <math.h>
#include <string.h>

#ifndef MAXN
#define MAXN 24
#endif

#define AE(i, j) a[(i) * n + (j)]

static inline double esgn(double x, double y) { return y >= 0.0 ? fabs(x) : -fabs(x); }

/* ------------------------------------------------------------------ */
/* Householder reduction to upper Hessenberg form (row-major, in place) */
static void hessenberg(int n, double *a)
{
    double v[MAXN];
    for (int k = 0; k < n - 2; k++) {
        double norm = 0.0;
        for (int i = k + 1; i < n; i++)
            norm += AE(i, k) * AE(i, k);
        norm = sqrt(norm);
        if (norm == 0.0 || !isfinite(norm))
            continue;
        double x0 = AE(k + 1, k);
        double alpha = -esgn(norm, x0);
        double d = x0 - alpha;
        if (d == 0.0)
            continue;
        v[0] = 1.0;
        double vnorm2 = 1.0;
        for (int i = k + 2; i < n; i++) {
            double t = AE(i, k) / d;
            v[i - (k + 1)] = t;
            vnorm2 += t * t;
        }
        double beta = 2.0 / vnorm2;
        for (int j = k; j < n; j++) {
            double s = 0.0;
            for (int i = k + 1; i < n; i++)
                s += v[i - (k + 1)] * AE(i, j);
            s *= beta;
            for (int i = k + 1; i < n; i++)
                AE(i, j) -= s * v[i - (k + 1)];
        }
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            double *row = a + i * n;
            for (int j = k + 1; j < n; j++)
                s += row[j] * v[j - (k + 1)];
            s *= beta;
            for (int j = k + 1; j < n; j++)
                row[j] -= s * v[j - (k + 1)];
        }
        for (int i = k + 2; i < n; i++)
            AE(i, k) = 0.0;
    }
}

/* ------------------------------------------------------------------ */
/* Francis double-shift QR on a Hessenberg matrix (Numerical Recipes)  */
static void hqr(int n, double *a, double *wr, double *wi)
{
    int nn, m, l, k, j, its, i, mmin;
    double z, y, x, w, v, u, t, s, r, q, p, anorm;

    anorm = fabs(AE(0, 0));
    for (i = 1; i < n; i++)
        for (j = i - 1; j < n; j++)
            anorm += fabs(AE(i, j));
    nn = n - 1;
    t = 0.0;
    while (nn >= 0) {
        its = 0;
        do {
            for (l = nn; l >= 1; l--) {
                s = fabs(AE(l - 1, l - 1)) + fabs(AE(l, l));
                if (s == 0.0)
                    s = anorm;
                if (fabs(AE(l, l - 1)) + s == s) {
                    AE(l, l - 1) = 0.0;
                    break;
                }
            }
            x = AE(nn, nn);
            if (l == nn) {
                wr[nn] = x + t;
                wi[nn] = 0.0;
                nn--;
            } else {
                y = AE(nn - 1, nn - 1);
                w = AE(nn, nn - 1) * AE(nn - 1, nn);
                if (l == nn - 1) {
                    p = 0.5 * (y - x);
                    q = p * p + w;
                    z = sqrt(fabs(q));
                    x += t;
                    if (q >= 0.0) {
                        z = p + esgn(z, p);
                        wr[nn - 1] = wr[nn] = x + z;
                        if (z != 0.0)
                            wr[nn] = x - w / z;
                        wi[nn - 1] = wi[nn] = 0.0;
                    } else {
                        wr[nn - 1] = wr[nn] = x + p;
                        wi[nn - 1] = -z;
                        wi[nn] = z;
                    }
                    nn -= 2;
                } else {
                    if (its == 60)
                        return; /* give up; caller verifies */
                    if (its == 10 || its == 20 || its == 40) {
                        t += x;
                        for (i = 0; i <= nn; i++)
                            AE(i, i) -= x;
                        s = fabs(AE(nn, nn - 1)) + fabs(AE(nn - 1, nn - 2));
                        y = x = 0.75 * s;
                        w = -0.4375 * s * s;
                    }
                    ++its;
                    for (m = nn - 2; m >= l; m--) {
                        z = AE(m, m);
                        r = x - z;
                        s = y - z;
                        p = (r * s - w) / AE(m + 1, m) + AE(m, m + 1);
                        q = AE(m + 1, m + 1) - z - r - s;
                        r = AE(m + 2, m + 1);
                        s = fabs(p) + fabs(q) + fabs(r);
                        p /= s;
                        q /= s;
                        r /= s;
                        if (m == l)
                            break;
                        u = fabs(AE(m, m - 1)) * (fabs(q) + fabs(r));
                        v = fabs(p) * (fabs(AE(m - 1, m - 1)) + fabs(z) + fabs(AE(m + 1, m + 1)));
                        if (u + v == v)
                            break;
                    }
                    for (i = m + 2; i <= nn; i++) {
                        AE(i, i - 2) = 0.0;
                        if (i != m + 2)
                            AE(i, i - 3) = 0.0;
                    }
                    for (k = m; k <= nn - 1; k++) {
                        if (k != m) {
                            p = AE(k, k - 1);
                            q = AE(k + 1, k - 1);
                            r = 0.0;
                            if (k != nn - 1)
                                r = AE(k + 2, k - 1);
                            x = fabs(p) + fabs(q) + fabs(r);
                            if (x != 0.0) {
                                p /= x;
                                q /= x;
                                r /= x;
                            }
                        }
                        s = esgn(sqrt(p * p + q * q + r * r), p);
                        if (s != 0.0) {
                            if (k == m) {
                                if (l != m)
                                    AE(k, k - 1) = -AE(k, k - 1);
                            } else {
                                AE(k, k - 1) = -s * x;
                            }
                            p += s;
                            x = p / s;
                            y = q / s;
                            z = r / s;
                            q /= p;
                            r /= p;
                            for (j = k; j <= nn; j++) {
                                p = AE(k, j) + q * AE(k + 1, j);
                                if (k != nn - 1) {
                                    p += r * AE(k + 2, j);
                                    AE(k + 2, j) -= p * z;
                                }
                                AE(k + 1, j) -= p * y;
                                AE(k, j) -= p * x;
                            }
                            mmin = nn < k + 3 ? nn : k + 3;
                            for (i = l; i <= mmin; i++) {
                                p = x * AE(i, k) + y * AE(i, k + 1);
                                if (k != nn - 1) {
                                    p += z * AE(i, k + 2);
                                    AE(i, k + 2) -= p * r;
                                }
                                AE(i, k + 1) -= p * q;
                                AE(i, k) -= p;
                            }
                        }
                    }
                }
            }
        } while (l < nn - 1);
    }
}

/* ------------------------------------------------------------------ */
/* LU with partial pivoting (row-major, in place)                      */
static int lu_factor(int n, double *M, int *piv)
{
    for (int k = 0; k < n; k++) {
        int p = k;
        double mx = fabs(M[k * n + k]);
        for (int i = k + 1; i < n; i++) {
            double t = fabs(M[i * n + k]);
            if (t > mx) {
                mx = t;
                p = i;
            }
        }
        piv[k] = p;
        if (mx == 0.0 || !isfinite(mx))
            return 0;
        if (p != k)
            for (int j = 0; j < n; j++) {
                double t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
        double d = M[k * n + k];
        for (int i = k + 1; i < n; i++) {
            double f = M[i * n + k] / d;
            M[i * n + k] = f;
            if (f != 0.0) {
                const double *rowk = M + k * n;
                double *rowi = M + i * n;
                for (int j = k + 1; j < n; j++)
                    rowi[j] -= f * rowk[j];
            }
        }
    }
    return 1;
}

static void lu_solve(int n, const double *LU, const int *piv, double *x)
{
    for (int k = 0; k < n; k++) {
        int p = piv[k];
        if (p != k) {
            double t = x[k];
            x[k] = x[p];
            x[p] = t;
        }
    }
    for (int i = 0; i < n; i++) {
        double s = x[i];
        const double *row = LU + i * n;
        for (int j = 0; j < i; j++)
            s -= row[j] * x[j];
        x[i] = s;
    }
    for (int i = n - 1; i >= 0; i--) {
        double s = x[i];
        const double *row = LU + i * n;
        for (int j = i + 1; j < n; j++)
            s -= row[j] * x[j];
        x[i] = s / row[i];
    }
}

/* inverse iteration: w <- (M^-1 w), a couple of times */
static int inverse_iter(int n, const double *LU, const int *piv, double *w, int iters)
{
    double tmp[MAXN];
    for (int it = 0; it < iters; it++) {
        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += w[i] * w[i];
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            return 0;
        for (int i = 0; i < n; i++)
            tmp[i] = w[i] / nrm;
        lu_solve(n, LU, piv, tmp);
        for (int i = 0; i < n; i++) {
            if (!isfinite(tmp[i]))
                return 0;
            w[i] = tmp[i];
        }
    }
    return 1;
}

/* check np.allclose(A v, lambda v) componentwise, with half the margin */
static int residual_ok(int n, const double *avr, const double *avi,
                       double lr, double li,
                       const double *vr, const double *vi)
{
    const double atol = 5e-9, rtol = 5e-6;
    for (int i = 0; i < n; i++) {
        double pr = lr * vr[i] - li * vi[i];
        double pi = lr * vi[i] + li * vr[i];
        if (fabs(avr[i] - pr) > atol + rtol * fabs(pr))
            return 0;
        if (fabs(avi[i] - pi) > atol + rtol * fabs(pi))
            return 0;
    }
    return 1;
}

/* ------------------------------------------------------------------ */
/* Solve the whole problem.  Writes lr/li (eigenvalue) and vr/vi
 * (eigenvector, split into real and imaginary parts).
 * Returns 1 on success, 0 if the caller should fall back to LAPACK.
 */
static int solve_dominant(int n, const double *a,
                          double *out_lr, double *out_li,
                          double *vr, double *vi)
{
    double wr[MAXN], wi[MAXN];
    double h[MAXN * MAXN];
    double anorm = 0.0;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            anorm += a[i * n + j] * a[i * n + j];
    anorm = sqrt(anorm);
    if (!(anorm > 0.0) || !isfinite(anorm))
        return 0;

    if (n == 1) {
        *out_lr = a[0];
        *out_li = 0.0;
        vr[0] = 1.0;
        vi[0] = 0.0;
        return 1;
    }

    if (n == 2) {
        /* closed form */
        double tr = a[0] + a[3];
        double det = a[0] * a[3] - a[1] * a[2];
        double half = 0.5 * tr;
        double disc = half * half - det;
        if (disc >= 0.0) {
            double sq = sqrt(disc);
            double l1 = half + sq, l2 = half - sq;
            double lam = fabs(l1) >= fabs(l2) ? l1 : l2;
            /* null vector of (A - lam I), pick the better conditioned row */
            double n0 = hypot(a[1], lam - a[0]);
            double n1 = hypot(lam - a[3], a[2]);
            if (n0 >= n1) {
                vr[0] = a[1];
                vr[1] = lam - a[0];
            } else {
                vr[0] = lam - a[3];
                vr[1] = a[2];
            }
            double nrm = hypot(vr[0], vr[1]);
            if (!(nrm > 0.0) || !isfinite(nrm))
                return 0;
            vr[0] /= nrm;
            vr[1] /= nrm;
            vi[0] = vi[1] = 0.0;
            /* Rayleigh quotient */
            double av0 = a[0] * vr[0] + a[1] * vr[1];
            double av1 = a[2] * vr[0] + a[3] * vr[1];
            double rq = vr[0] * av0 + vr[1] * av1;
            *out_lr = rq;
            *out_li = 0.0;
            return residual_ok(n, &av0, vi, rq, 0.0, vr, vi);
        } else {
            double b = sqrt(-disc);
            double lr = half, li = b;
            /* eigenvector for lr + i li */
            double n0 = hypot(a[1], hypot(lr - a[0], li));
            double n1 = hypot(hypot(lr - a[3], li), a[2]);
            if (n0 >= n1) {
                vr[0] = a[1];
                vi[0] = 0.0;
                vr[1] = lr - a[0];
                vi[1] = li;
            } else {
                vr[0] = lr - a[3];
                vi[0] = li;
                vr[1] = a[2];
                vi[1] = 0.0;
            }
            double nrm = hypot(hypot(vr[0], vi[0]), hypot(vr[1], vi[1]));
            if (!(nrm > 0.0) || !isfinite(nrm))
                return 0;
            vr[0] /= nrm;
            vi[0] /= nrm;
            vr[1] /= nrm;
            vi[1] /= nrm;
            /* Rayleigh quotient v^H A v */
            double avr0 = a[0] * vr[0] + a[1] * vr[1];
            double avi0 = a[0] * vi[0] + a[1] * vi[1];
            double avr1 = a[2] * vr[0] + a[3] * vr[1];
            double avi1 = a[2] * vi[0] + a[3] * vi[1];
            double numr = vr[0] * avr0 + vi[0] * avi0 + vr[1] * avr1 + vi[1] * avi1;
            double numi = vr[0] * avi0 - vi[0] * avr0 + vr[1] * avi1 - vi[1] * avr1;
            *out_lr = numr;
            *out_li = numi;
            double avr[2] = {avr0, avr1}, avi[2] = {avi0, avi1};
            return residual_ok(n, avr, avi, numr, numi, vr, vi);
        }
    }

    memcpy(h, a, sizeof(double) * n * n);
    hessenberg(n, h);
    hqr(n, h, wr, wi);

    /* dominant eigenvalue (ties prefer positive imaginary part, like LAPACK) */
    int idx = 0;
    double best = -1.0;
    for (int i = 0; i < n; i++) {
        double mag = hypot(wr[i], wi[i]);
        if (!isfinite(mag))
            return 0;
        if (mag > best) {
            best = mag;
            idx = i;
        } else if (mag >= best * (1.0 - 1e-12) && wi[i] > 0.0 && wi[idx] < 0.0) {
            idx = i;
        }
    }
    double lr = wr[idx], li = wi[idx];

    double M[MAXN * MAXN], w[MAXN];
    int piv[MAXN];

    if (fabs(li) <= 1e-9 * (fabs(lr) + anorm)) {
        /* ---------- real eigenvalue ---------- */
        li = 0.0;
        memcpy(M, a, sizeof(double) * n * n);
        for (int i = 0; i < n; i++)
            M[i * n + i] -= lr;
        if (!lu_factor(n, M, piv))
            return 0;
        for (int i = 0; i < n; i++)
            w[i] = 1.0 + 0.5 * (double)i;
        if (!inverse_iter(n, M, piv, w, 3))
            return 0;
        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += w[i] * w[i];
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            return 0;
        for (int i = 0; i < n; i++) {
            w[i] /= nrm;
            vr[i] = w[i];
            vi[i] = 0.0;
        }
        double av[MAXN];
        double num = 0.0;
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            const double *row = a + i * n;
            for (int j = 0; j < n; j++)
                s += row[j] * w[j];
            av[i] = s;
            num += w[i] * s;
        }
        *out_lr = num; /* ||w|| == 1 */
        *out_li = 0.0;
        return residual_ok(n, av, vi, num, 0.0, vr, vi);
    } else {
        /* ---------- complex conjugate pair ---------- */
        /* M = (A - lr I)^2 + li^2 I ; null space = invariant subspace */
        double B[MAXN * MAXN];
        memcpy(B, a, sizeof(double) * n * n);
        for (int i = 0; i < n; i++)
            B[i * n + i] -= lr;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double s = 0.0;
                const double *ri = B + i * n;
                for (int k = 0; k < n; k++)
                    s += ri[k] * B[k * n + j];
                M[i * n + j] = s;
            }
            M[i * n + i] += li * li;
        }
        if (!lu_factor(n, M, piv))
            return 0;
        for (int i = 0; i < n; i++)
            w[i] = 1.0 + 0.5 * (double)i;
        if (!inverse_iter(n, M, piv, w, 3))
            return 0;

        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += w[i] * w[i];
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            return 0;
        for (int i = 0; i < n; i++)
            w[i] /= nrm;

        /* z = (A w - lr w)/li ;  v = w - i z */
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            const double *row = a + i * n;
            for (int j = 0; j < n; j++)
                s += row[j] * w[j];
            vr[i] = w[i];
            vi[i] = -(s - lr * w[i]) / li;
        }
        double avr[MAXN], avi[MAXN];
        for (int i = 0; i < n; i++) {
            double sr = 0.0, si = 0.0;
            const double *row = a + i * n;
            for (int j = 0; j < n; j++) {
                sr += row[j] * vr[j];
                si += row[j] * vi[j];
            }
            avr[i] = sr;
            avi[i] = si;
        }
        /* Rayleigh quotient v^H A v / v^H v */
        double numr = 0.0, numi = 0.0, den = 0.0;
        for (int i = 0; i < n; i++) {
            numr += vr[i] * avr[i] + vi[i] * avi[i];
            numi += vr[i] * avi[i] - vi[i] * avr[i];
            den += vr[i] * vr[i] + vi[i] * vi[i];
        }
        if (!(den > 0.0) || !isfinite(den))
            return 0;
        *out_lr = numr / den;
        *out_li = numi / den;
        return residual_ok(n, avr, avi, *out_lr, *out_li, vr, vi);
    }
}

