/* Python glue for the small-matrix dominant eigenpair solver. */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>

#include "_eigen_core.h"

static PyObject *dominant_arr(PyObject *self, PyObject *arg)
{
    PyArrayObject *arr = (PyArrayObject *)arg;
    if (!PyArray_Check(arr))
        Py_RETURN_NONE;
    if (PyArray_NDIM(arr) != 2)
        Py_RETURN_NONE;
    int n = (int)PyArray_DIM(arr, 0);
    if ((int)PyArray_DIM(arr, 1) != n || n < 1 || n > MAXN)
        Py_RETURN_NONE;
    if (PyArray_TYPE(arr) != NPY_DOUBLE)
        Py_RETURN_NONE;

    const char *base = (const char *)PyArray_DATA(arr);
    npy_intp s0 = PyArray_STRIDE(arr, 0), s1 = PyArray_STRIDE(arr, 1);

    double a[MAXN * MAXN];
    if (s1 == sizeof(double) && s0 == (npy_intp)n * sizeof(double)) {
        memcpy(a, base, sizeof(double) * n * n);
    } else {
        for (int i = 0; i < n; i++) {
            const char *row = base + i * s0;
            for (int j = 0; j < n; j++)
                a[i * n + j] = *(const double *)(row + j * s1);
        }
    }

    double lr, li;
    double vr[MAXN], vi[MAXN];
    if (!solve_dominant(n, a, &lr, &li, vr, vi))
        Py_RETURN_NONE;

    npy_intp dims[1] = {n};
    PyObject *val, *vec, *res;

    if (li == 0.0) {
        vec = PyArray_SimpleNew(1, dims, NPY_DOUBLE);
        if (!vec)
            return NULL;
        memcpy(PyArray_DATA((PyArrayObject *)vec), vr, sizeof(double) * n);
        val = PyFloat_FromDouble(lr);
    } else {
        vec = PyArray_SimpleNew(1, dims, NPY_CDOUBLE);
        if (!vec)
            return NULL;
        double *out = (double *)PyArray_DATA((PyArrayObject *)vec);
        for (int i = 0; i < n; i++) {
            out[2 * i] = vr[i];
            out[2 * i + 1] = vi[i];
        }
        val = PyComplex_FromDoubles(lr, li);
    }
    if (!val) {
        Py_DECREF(vec);
        return NULL;
    }
    res = PyTuple_Pack(2, val, vec);
    Py_DECREF(val);
    Py_DECREF(vec);
    return res;
}

static PyMethodDef Methods[] = {
    {"dominant", dominant_arr, METH_O, "dominant eigenpair"},
    {NULL, NULL, 0, NULL},
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigenfast", NULL, -1, Methods,
};

PyMODINIT_FUNC PyInit__eigenfast(void)
{
    import_array();
    return PyModule_Create(&moduledef);
}

