/* ------------------------------------------------------------------ */
/* Diagonal balancing (Parlett-Reinsch, as in LAPACK dgebal).
 * A <- D^-1 A D with D = diag(dscale); eigenvectors transform back as v = D x. */
static void balance(int n, double *a, double *dscale)
{
    const double radix = 2.0, sqrdx = 4.0, factor = 0.95;
    for (int i = 0; i < n; i++)
        dscale[i] = 1.0;
    int done = 0;
    while (!done) {
        done = 1;
        for (int i = 0; i < n; i++) {
            double c = 0.0, r = 0.0;
            for (int j = 0; j < n; j++) {
                if (j != i) {
                    c += fabs(a[j * n + i]);
                    r += fabs(a[i * n + j]);
                }
            }
            if (c == 0.0 || r == 0.0)
                continue;
            double g = r / radix;
            double f = 1.0, s = c + r;
            while (c < g) {
                f *= radix;
                c *= sqrdx;
            }
            g = r * radix;
            while (c >= g) {
                f /= radix;
                c /= sqrdx;
            }
            if ((c + r) / f < factor * s) {
                done = 0;
                dscale[i] *= f;
                double *row = a + i * n;
                for (int j = 0; j < n; j++) {
                    row[j] /= f;
                    a[j * n + i] *= f;
                }
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* LU with partial pivoting (row-major, in place)                      */

