        if (!(nrm > 0.0) || !isfinite(nrm))
            return 0;
        /* back to the original scaling and normalise */
        double nn = 0.0;
        for (int i = 0; i < n; i++) {
            vr[i] = dscale[i] * w[i] / nrm;
            vi[i] = 0.0;
            nn += vr[i] * vr[i];
        }
        nn = sqrt(nn);
        if (!(nn > 0.0) || !isfinite(nn))
            return 0;
        for (int i = 0; i < n; i++)
            vr[i] /= nn;

        double av[MAXN];
        double num = 0.0;
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            const double *row = a + i * n;
            for (int j = 0; j < n; j++)
                s += row[j] * vr[j];
            av[i] = s;
            num += vr[i] * s;
        }
        *out_lr = num; /* ||v|| == 1 */
        *out_li = 0.0;
        return residual_ok(n, av, vi, num, 0.0, vr, vi);
    } else {
        /* ---------- complex conjugate pair ---------- */
        /* M = (A' - lr I)^2 + li^2 I ; null space = invariant subspace */
        int factored = 0;
        for (int attempt = 0; attempt < 2 && !factored; attempt++) {
            double shift = lr + (attempt ? delta : 0.0);
            memcpy(B, ab, sizeof(double) * n * n);
            for (int i = 0; i < n; i++)
                B[i * n + i] -= shift;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    double s = 0.0;
                    const double *ri = B + i * n;
                    for (int k = 0; k < n; k++)
                        s += ri[k] * B[k * n + j];
                    M[i * n + j] = s;
                }
                M[i * n + i] += li * li;
            }
            factored = lu_factor(n, M, piv);
        }
        if (!factored)
            return 0;
        for (int i = 0; i < n; i++)
            w[i] = 1.0 + 0.5 * (double)i;
        if (!inverse_iter(n, M, piv, w, 3))
            return 0;

        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += w[i] * w[i];
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            return 0;
        for (int i = 0; i < n; i++)
            w[i] /= nrm;

        /* z = (A' w - lr w)/li ;  x = w - i z ;  v = D x */
        double den = 0.0;
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            const double *row = ab + i * n;
            for (int j = 0; j < n; j++)
                s += row[j] * w[j];
            vr[i] = dscale[i] * w[i];
            vi[i] = -dscale[i] * (s - lr * w[i]) / li;
            den += vr[i] * vr[i] + vi[i] * vi[i];
        }
        if (!(den > 0.0) || !isfinite(den))
            return 0;
        den = 1.0 / sqrt(den);
        for (int i = 0; i < n; i++) {
            vr[i] *= den;
            vi[i] *= den;
        }
        double avr[MAXN], avi[MAXN];
        for (int i = 0; i < n; i++) {
            double sr = 0.0, si = 0.0;
            const double *row = a + i * n;
            for (int j = 0; j < n; j++) {
                sr += row[j] * vr[j];
                si += row[j] * vi[j];
            }
            avr[i] = sr;
            avi[i] = si;
        }
        /* Rayleigh quotient, ||v|| == 1 */
        double numr = 0.0, numi = 0.0;
        for (int i = 0; i < n; i++) {
            numr += vr[i] * avr[i] + vi[i] * avi[i];
            numi += vr[i] * avi[i] - vi[i] * avr[i];
        }
        *out_lr = numr;
        *out_li = numi;
        return residual_ok(n, avr, avi, numr, numi, vr, vi);
    }
}

anorm = sqrt(anorm);
if (anorm == 0.0) {
    /* zero matrix: every vector is an eigenvector for 0 */
    *out_lr = 0.0;
    *out_li = 0.0;
    vr[0] = 1.0;
    vi[0] = 0.0;
    for (int i = 1; i < n; i++) {
        vr[i] = 0.0;
        vi[i] = 0.0;
    }
    return 1;
}
if (!isfinite(anorm))
    return 0;

